package com.infinitylibrary.writing;
import java.util.*;
/** Safe inline book markup. No command, link or MiniMessage event parser is involved. */
public final class BookTypography {
 public static String render(String source){StringBuilder result=new StringBuilder();String[] lines=source.split("\n",-1);for(int row=0;row<lines.length;row++){if(row>0)result.append('\n');String line=lines[row];if(line.equals("---")){result.append("────────────");continue;}boolean heading=line.startsWith("# "),bold=false,italic=false;int i=heading?2:0;if(heading)result.append("§l");while(i<line.length()){char c=line.charAt(i);if(c=='\\'&&i+1<line.length()&&"*_\\".indexOf(line.charAt(i+1))>=0){result.append(line.charAt(i+1));i+=2;continue;}if(line.startsWith("**",i)&&(bold||line.indexOf("**",i+2)>=0)){bold=!bold;if(bold)result.append("§l");else{result.append("§r");if(heading)result.append("§l");if(italic)result.append("§o");}i+=2;continue;}if(c=='_'&&(italic||line.indexOf('_',i+1)>=0&&(i==0||!Character.isLetterOrDigit(line.charAt(i-1))))){italic=!italic;if(italic)result.append("§o");else{result.append("§r");if(bold||heading)result.append("§l");}i++;continue;}result.append(c);i++;}if(heading||bold||italic)result.append("§r");}if(result.length()>BookDraft.MAX_PAGE_LENGTH)throw new IllegalArgumentException("Formatted page exceeds the page limit; shorten it before publishing");return result.toString();}
 public static String apply(String page,String operation){return switch(operation){case "bold","italic"->{String marker=operation.equals("bold")?"**":"_";yield String.join("\n",Arrays.stream(page.split("\n",-1)).map(line->line.isBlank()?line:marker+line+marker).toList());}case "heading"->"# "+page;case "divider"->page+(page.isEmpty()?"":"\n")+"---";default->throw new IllegalArgumentException("Unknown formatting tool");};}
 private BookTypography(){}
}
